# Generated by governance model version 1. Only the generator changes this file.
"""Merge watch: records misses after merges as `miss` issues, and never blocks anything.

The workflow `.github/workflows/merge-watch.yml` runs this script from the default branch's
checkout. It is never a required check. It reads the event, then GitHub through `gh api`,
and opens one miss record per miss, in the format `docs/agents/issue-tracker.md` gives
(Miss records), labelled `miss`.

On `push` to the default branch, for each pushed commit:

- the merged PR is the one whose squash commit it is. A commit that is only part of a merged
  PR's history is left to that PR's merge commit; a commit with no merged PR at all records a
  process miss, `push-without-pr`;
- a `Reverts:` line in the merged PR's body records an escape, `revert`, naming the reverted
  commit's PR;
- every review missing from the merged PR's head by its declared tier records one process
  miss, `missing-review`, listing each missing review by its Merge summary kind
  (`docs/agents/review.md`), or `merge-summary`:
  - `bugbot`, at every tier: a completed `Cursor Bugbot` check run from the `cursor` app on
    the head, its conclusion `success`, `neutral` or `failure`. At low and medium a
    completed Codex marker for the head counts instead;
  - `codex`, at high: a `codex-review-state:v1` marker in a `chatgpt-codex-connector[bot]`
    comment whose `code_review.commit_sha` is the head and `code_review.status` `completed`;
  - `reviewer`, at medium and high: the agent account's newest `Reviewer` status on the head
    is `success`;
  - `merge-summary`, at every tier: the agent account's newest comment titled
    `## Merge summary: <tier> at <short sha>` for the declared tier and the head, whose second
    line `Required reviews: <kind>=<state>, ...` reads. A review counts as present when
    that line records habit's accepted reduction in the one form allowed: `bugbot=reduced`
    or `codex=reduced`, at high, at most one per summary. Any other `reduced`, and
    `substituted` anywhere but `bugbot` at low and medium, counts that review as missing.

  A body with no readable `Risk:` line is judged at high.

On `workflow_run`, a push-triggered run on the default branch of any workflow but Merge watch
that concludes `failure` records an escape, `red-default-branch`, naming the merged PR of the
run's commit, unless a `red-default-branch` record is already open.

A format it can't read, or a GitHub read that fails, counts that review or fact as absent, so
it yields a false miss record, never a blocked merge. A record whose title and `Observed:`
line an open record already has isn't opened again, so a rerun adds nothing. Two runs at once
can each read no open record, so two workflows failing together may open two
`red-default-branch` records: a concurrency group would cancel a pending run and lose its
record instead.

The `Risk:` and `Reverts:` lines and the record are read with the gate script's parser,
imported from beside this file. Python 3's standard library at the 3.9 level, plus `gh`.
"""

import argparse
import json
import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True

import gate  # noqa: E402

LABEL = "miss"
FOUND_BY = "Merge watch"
WORKFLOW = ".github/workflows/merge-watch.yml"
RECORD = ".github/governance/record.yml"

BUGBOT_CHECK = "Cursor Bugbot"
BUGBOT_APP = "cursor"
# Cursor sets one of these on a review it finished: findings leave it neutral, or failure when
# configured to fail on them. A run GitHub cancelled, timed out or marked stale is no review.
BUGBOT_COMPLETED = ("success", "neutral", "failure")
CODEX_LOGIN = "chatgpt-codex-connector[bot]"
CODEX_MARKER = re.compile(r"<!-- codex-review-state:v1 (\{.*?\}) -->", re.S)
REVIEWER_CONTEXT = "Reviewer"

# The Merge summary's fixed first two lines (docs/agents/review.md, Merge summary, On the PR).
SUMMARY_TITLE = re.compile(r"## Merge summary: (low|medium|high) at ([0-9a-f]{7})")
SUMMARY_REVIEWS = "Required reviews: "
SUMMARY_REVIEW = re.compile(r"([a-z-]+)=([a-z]+)")
KINDS = ("self-verification", "bugbot", "codex", "reviewer", "security")
STATES = ("clear", "substituted", "reduced")
MERGE_SUMMARY = "merge-summary"
REDUCIBLE = ("bugbot", "codex")


class ReadError(Exception):
    """GitHub couldn't give a fact Merge watch reads."""


def _same_login(a, b):
    return bool(a) and bool(b) and a.lower() == b.lower()


def _read(read, path, default):
    try:
        return read(path)
    except ReadError:
        return default


def record(merged_pr, kind, category, observed):
    """One miss record: its title, its six field lines and the `miss` label."""
    title = "Miss: %s, %s" % (kind, category)
    if merged_pr is not None:
        title += " in #%d" % merged_pr
    lines = (
        "Merged PR: %s" % ("#%d" % merged_pr if merged_pr is not None else "none"),
        "Kind: %s" % kind,
        "Category: %s" % category,
        "Observed: %s" % observed,
        "Found by: %s" % FOUND_BY,
        "Bug issue: none",
    )
    return {"title": title, "body": "\n".join(lines) + "\n", "labels": [LABEL]}


def _field(body, name):
    for line in (body or "").replace("\r\n", "\n").split("\n"):
        if line.startswith(name + ": "):
            return line[len(name) + 2:]
    return None


def _open_records(read, repository):
    issues = _read(read, "repos/%s/issues?labels=%s&state=open" % (repository, LABEL), [])
    return [issue for issue in issues if "pull_request" not in issue]


def _merged_pr(read, repository, default_branch, sha):
    """(the PR merged as sha, or None; whether sha is in another merged PR's history). ReadError when unread."""
    merged = [
        pull for pull in read("repos/%s/commits/%s/pulls" % (repository, sha))
        if pull.get("merged_at") and (pull.get("base") or {}).get("ref") == default_branch
    ]
    for pull in merged:
        if pull.get("merge_commit_sha") == sha:
            return pull, False
    return None, bool(merged)


def _bugbot(read, repository, head):
    runs = _read(read, "repos/%s/commits/%s/check-runs?check_name=Cursor%%20Bugbot&filter=all" % (repository, head), [])
    return any(
        run.get("name") == BUGBOT_CHECK
        and (run.get("app") or {}).get("slug") == BUGBOT_APP
        and run.get("status") == "completed"
        and run.get("conclusion") in BUGBOT_COMPLETED
        for run in runs
    )


def _reviewer(read, repository, head, agent_account):
    """Whether the agent account's newest `Reviewer` status on the head is success; GitHub lists the newest first."""
    for status in _read(read, "repos/%s/commits/%s/statuses" % (repository, head), []):
        if status.get("context") == REVIEWER_CONTEXT and _same_login((status.get("creator") or {}).get("login"), agent_account):
            return status.get("state") == "success"
    return False


def _codex(comments, head):
    for comment in comments:
        if (comment.get("user") or {}).get("login") != CODEX_LOGIN:
            continue
        for match in CODEX_MARKER.finditer(comment.get("body") or ""):
            try:
                review = json.loads(match.group(1)).get("code_review")
            except (ValueError, AttributeError):
                continue
            if isinstance(review, dict) and review.get("commit_sha") == head and review.get("status") == "completed":
                return True
    return False


def _summary_states(line):
    """The `Required reviews:` line's {kind: state}, or None when it doesn't read."""
    if not line.startswith(SUMMARY_REVIEWS):
        return None
    states, order = {}, []
    for item in line[len(SUMMARY_REVIEWS):].rstrip(" \t").split(", "):
        match = SUMMARY_REVIEW.fullmatch(item)
        if not match or match.group(1) not in KINDS or match.group(2) not in STATES or match.group(1) in states:
            return None
        states[match.group(1)] = match.group(2)
        order.append(KINDS.index(match.group(1)))
    return states if order == sorted(order) else None


def _summary(comments, agent_account, tier, head):
    """The newest Merge summary for the tier and head, as {kind: state}; None when absent or its line doesn't read."""
    for comment in reversed(comments):
        if not _same_login((comment.get("user") or {}).get("login"), agent_account):
            continue
        lines = (comment.get("body") or "").replace("\r\n", "\n").split("\n")
        title = SUMMARY_TITLE.fullmatch(lines[0].rstrip(" \t"))
        if title and title.group(1) == tier and title.group(2) == head[:7]:
            return _summary_states(lines[1]) if len(lines) > 1 else None
    return None


def missing_reviews(read, repository, agent_account, tier, head, pull_number):
    """Each review missing from the head at the tier: Merge summary kinds in their order, then `merge-summary`."""
    comments = _read(read, "repos/%s/issues/%d/comments" % (repository, pull_number), [])
    summary = _summary(comments, agent_account, tier, head)
    states = summary or {}
    reduced = [kind for kind in states if states[kind] == "reduced"]
    accepted, refused = set(), set()
    for kind, state in states.items():
        if state == "reduced":
            if tier == "high" and kind in REDUCIBLE and len(reduced) == 1:
                accepted.add(kind)
            else:
                refused.add(kind)
        elif state == "substituted" and not (kind == "bugbot" and tier in ("low", "medium")):
            refused.add(kind)
    required = ["bugbot"] + (["codex"] if tier == "high" else []) + (["reviewer"] if tier != "low" else [])
    codex = _codex(comments, head)
    present = {
        "bugbot": lambda: _bugbot(read, repository, head) or (tier in ("low", "medium") and codex),
        "codex": lambda: codex,
        "reviewer": lambda: _reviewer(read, repository, head, agent_account),
    }
    missing = [
        kind for kind in KINDS
        if kind in refused or (kind in required and kind not in accepted and not present[kind]())
    ]
    if summary is None:
        missing.append(MERGE_SUMMARY)
    return missing


def _judge_pull(read, repository, agent_account, pull, squash):
    records = []
    number, head = pull["number"], pull["head"]["sha"]
    body = gate.parse_body(pull.get("body") or "")
    reverts = body["reverts"]
    if isinstance(reverts, dict):
        try:
            reverted, _ = _merged_pr(read, repository, pull["base"]["ref"], reverts["sha"])
        except ReadError:
            reverted = None
        records.append(record(
            reverted["number"] if reverted else None, "escape", "revert",
            "#%d, merged as %s, reverted %s, and its body had a `Reverts:` line." % (number, squash, reverts["sha"]),
        ))
    elif reverts is not None:
        records.append(record(
            None, "escape", "revert",
            "#%d, merged as %s, has a `Reverts:` line that doesn't read (%s), so the reverted PR is unknown."
            % (number, squash, reverts),
        ))
    risk = body["risk"]
    if isinstance(risk, dict):
        tier, declared = risk["tier"], "declared %s" % risk["tier"]
    else:
        tier, declared = "high", "declared no readable tier (its `Risk:` line is %s), judged at high" % risk
    missing = missing_reviews(read, repository, agent_account, tier, head, number)
    if missing:
        records.append(record(
            number, "process miss", "missing-review",
            "Merged head %s, %s, lacks: %s." % (head, declared, ", ".join(missing)),
        ))
    return records


def _on_push(event, read, repository, default_branch, agent_account):
    records = []
    for commit in event.get("commits") or []:
        sha = commit["id"]
        try:
            pull, in_history = _merged_pr(read, repository, default_branch, sha)
        except ReadError:
            pull, in_history = None, False
        if pull is not None:
            records.extend(_judge_pull(read, repository, agent_account, pull, sha))
        elif not in_history:
            records.append(record(
                None, "process miss", "push-without-pr",
                "Commit %s was pushed to %s with no merged PR." % (sha, default_branch),
            ))
    return records


def _on_workflow_run(event, read, repository, default_branch, open_records):
    run = event["workflow_run"]
    if (
        run.get("event") != "push"
        or run.get("conclusion") != "failure"
        or run.get("head_branch") != default_branch
        or (run.get("path") or "").split("@")[0] == WORKFLOW
    ):
        return []
    if any(_field(issue.get("body"), "Category") == "red-default-branch" for issue in open_records):
        return []
    sha = run["head_sha"]
    try:
        pull, _ = _merged_pr(read, repository, default_branch, sha)
    except ReadError:
        pull = None
    return [record(
        pull["number"] if pull else None, "escape", "red-default-branch",
        "Workflow %s failed on its push-triggered run %s at commit %s." % (run.get("name"), run.get("html_url"), sha),
    )]


def decide(event_name, event, agent_account, read):
    """The miss records to open for one event.

    `read(path)` returns the JSON list GitHub gives for a REST path, every page joined (a
    check-runs answer's `check_runs`), or raises ReadError. `agent_account` is the record's,
    or None when the record doesn't parse. Each record is {"title", "body", "labels"}.
    """
    repository = event["repository"]["full_name"]
    default_branch = event["repository"]["default_branch"]
    if event_name == "push" and event.get("ref") == "refs/heads/" + default_branch:
        open_records = _open_records(read, repository)
        records = _on_push(event, read, repository, default_branch, agent_account)
    elif event_name == "workflow_run":
        open_records = _open_records(read, repository)
        records = _on_workflow_run(event, read, repository, default_branch, open_records)
    else:
        return []
    seen = set((issue.get("title"), _field(issue.get("body"), "Observed")) for issue in open_records)
    return [rec for rec in records if (rec["title"], _field(rec["body"], "Observed")) not in seen]


# The entry the workflow runs.

PER_PAGE = 100


class GitHub(object):
    """`read` through `gh api`, every page of a list; each path that couldn't be read is kept in `unreadable`."""

    def __init__(self):
        self.unreadable = []

    def __call__(self, path):
        items, page = [], 1
        while True:
            paged = "%s%sper_page=%d&page=%d" % (path, "&" if "?" in path else "?", PER_PAGE, page)
            result = subprocess.run(["gh", "api", paged], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            try:
                if result.returncode != 0:
                    raise ValueError(" ".join(result.stderr.decode("utf-8", "replace").split()) or "gh failed")
                data = json.loads(result.stdout.decode("utf-8"))
                if isinstance(data, dict) and isinstance(data.get("check_runs"), list):
                    data = data["check_runs"]
                if not isinstance(data, list):
                    raise ValueError("the answer isn't a list")
            except ValueError as error:
                self.unreadable.append("%s: %s" % (paged, error))
                raise ReadError(path)
            items.extend(data)
            if len(data) < PER_PAGE:
                return items
            page += 1


def _post(repository, rec):
    """Open the record as an issue; True when GitHub took it."""
    posted = subprocess.run(
        ["gh", "api", "--method", "POST", "repos/%s/issues" % repository, "--input", "-"],
        input=json.dumps(rec, sort_keys=True).encode("utf-8"),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    return posted.returncode == 0


def main(argv=None):
    parser = argparse.ArgumentParser(description="Merge watch's miss records for the event in GITHUB_EVENT_PATH.")
    parser.add_argument("--post", action="store_true", help="open each record as a `miss` issue")
    args = parser.parse_args(argv)
    with open(os.environ["GITHUB_EVENT_PATH"], encoding="utf-8") as handle:
        event = json.load(handle)
    event_name = os.environ["GITHUB_EVENT_NAME"]
    try:
        with open(os.path.join(os.getcwd(), *RECORD.split("/")), "rb") as handle:
            agent_account = gate.parse_record(handle.read())["agent_account"]
    except (OSError, gate.RecordError) as error:
        agent_account = None
        print("UNREADABLE %s: %s; no comment or status counts as the agent account's" % (RECORD, error))
    github = GitHub()
    records = decide(event_name, event, agent_account, github)
    failed = agent_account is None or bool(github.unreadable)
    for line in github.unreadable:
        print("UNREADABLE " + line)
    for rec in records:
        print("MISS %s. %s" % (rec["title"], _field(rec["body"], "Observed")))
        if args.post and not _post(event["repository"]["full_name"], rec):
            print("FAIL opening the record %s" % rec["title"])
            failed = True
    if not records:
        print("No miss in this %s event." % event_name)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
